-- Delete the 620 system ownership rows the sync should never have written (found 2026-10-12).
--
-- 1. Cynet Health, 375 rows: changes first seen BEFORE the data team cutoff (2026-10-02 12:50 UTC).
--    That history is the data team's; the deal sheet's own versions before then come from the
--    2026-08-19 table reload, which stamped every version with that day's owners. So "changes" read
--    from them skip whoever held the seat in between and land on the data team's dates:
--    H13017_H13231 LEVEL_2_CSM: data team Briana -> Jodi (04-05), Jodi -> Damian (05-24);
--    sync Briana -> Damian (04-05). 61 of the 62 same-SKU/role/date clashes with data team rows are
--    these. Code now logs only changes first seen after the cutoff, for health
--    (config.ownershipLogDataTeamCutoff, ownershipChangeLogRules rule 2).
-- 2. Canada, 245 VP rows: Varun Gupta -> NA (60) and NA -> Varun Gupta (185). The Sr. VP title fix
--    was deployed but fix_canada_vp_varun_backfill.sql was not run, so blank VP versions sit next to
--    Varun ones. Run that backfill FIRST, or the next Canada trigger writes them again.
--
-- Kept (332): health changes first seen after the cutoff (e.g. H15370 Sonam -> Sid on 10-11,
-- 1470999 Abdul Sami -> Aaron Panchal) and Canada's real changes (Rohit Sharma's promotion).
-- Data team rows (EDITED_BY = 'DATA_TEAM_SYNC') are not touched.
--
-- ORDER: deploy the cutoff code -> run fix_canada_vp_varun_backfill.sql -> run this file.
-- (Deleting before the deploy lets the old code write the health rows again on its next run.)

-- 1. Backup.
CREATE TABLE IF NOT EXISTS `cynetdatabase.rr_project_data.ownership_change_logs_backup_20261012`
COPY `cynetdatabase.rr_project_data.ownership_change_logs`;

-- 2. Preview: expected 620 rows, none from the data team.
SELECT LEFT(CONTRACT_ID, 3) AS domain, OWNERSHIP_ROLE, COUNT(*) AS n, COUNTIF(EDITED_BY = 'DATA_TEAM_SYNC') AS data_team
FROM `cynetdatabase.rr_project_data.ownership_change_logs`
