-- 4. Check: no system row left on a data team SKU + role + effective date, except H15370
--    (expected 1 row: H15370 RECRUITER Sonam -> Sid).
SELECT s.SKU_NO, s.OWNERSHIP_ROLE, s.PREVIOUS_OWNER_NAME, s.NEW_OWNER_NAME, s.OWNERSHIP_EFFECTIVE_DATE
FROM `cynetdatabase.rr_project_data.ownership_change_logs` s
JOIN `cynetdatabase.rr_project_data.ownership_change_logs` d
  ON UPPER(TRIM(d.SKU_NO)) = UPPER(TRIM(s.SKU_NO))
 AND d.OWNERSHIP_ROLE = s.OWNERSHIP_ROLE
 AND d.OWNERSHIP_EFFECTIVE_DATE = s.OWNERSHIP_EFFECTIVE_DATE
WHERE s.EDITED_BY IS NULL AND d.EDITED_BY = 'DATA_TEAM_SYNC';
